01154 static int find_extensionsGL(void) {
01155     if (!get_exts()) return 0;
01156     (void)&has_ext;
01157     free_exts();
01158     return 1;
01159 }
01160 
01161 static void find_coreGL(void) {
01162 
01163     /* Thank you @elmindreda
01164      * https://github.com/elmindreda/greg/blob/master/templates/greg.c.in#L176
01165      * https://github.com/glfw/glfw/blob/master/src/context.c#L36
01166      */
01167     int i, major, minor;
01168 
01169     const char* version;
01170     const char* prefixes[] = {
01171         "OpenGL ES-CM ",
01172         "OpenGL ES-CL ",
01173         "OpenGL ES ",
01174         NULL
01175     };
01176 
01177     version = (const char*) glGetString(GL_VERSION);
01178     if (!version) return;
01179 
01180     for (i = 0;  prefixes[i];  i++) {
01181         const size_t length = strlen(prefixes[i]);
01182         if (strncmp(version, prefixes[i], length) == 0) {
01183             version += length;
01184             break;
01185         }
01186     }
01187 
01188 /* PR #18 */
01189 #ifdef _MSC_VER
01190     sscanf_s(version, "%d.%d", &major, &minor);
01191 #else
01192     sscanf(version, "%d.%d", &major, &minor);
01193 #endif
01194 
01195     GLVersion.major = major; GLVersion.minor = minor;
01196     max_loaded_major = major; max_loaded_minor = minor;
01197     GLAD_GL_VERSION_1_0 = (major == 1 && minor >= 0) || major > 1;
01198     GLAD_GL_VERSION_1_1 = (major == 1 && minor >= 1) || major > 1;
01199     GLAD_GL_VERSION_1_2 = (major == 1 && minor >= 2) || major > 1;
01200     GLAD_GL_VERSION_1_3 = (major == 1 && minor >= 3) || major > 1;
01201     GLAD_GL_VERSION_1_4 = (major == 1 && minor >= 4) || major > 1;
01202     GLAD_GL_VERSION_1_5 = (major == 1 && minor >= 5) || major > 1;
01203     GLAD_GL_VERSION_2_0 = (major == 2 && minor >= 0) || major > 2;
01204     GLAD_GL_VERSION_2_1 = (major == 2 && minor >= 1) || major > 2;
01205     GLAD_GL_VERSION_3_0 = (major == 3 && minor >= 0) || major > 3;
01206     GLAD_GL_VERSION_3_1 = (major == 3 && minor >= 1) || major > 3;
01207     GLAD_GL_VERSION_3_2 = (major == 3 && minor >= 2) || major > 3;
01208     GLAD_GL_VERSION_3_3 = (major == 3 && minor >= 3) || major > 3;
01209     GLAD_GL_VERSION_4_0 = (major == 4 && minor >= 0) || major > 4;
01210     if (GLVersion.major > 4 || (GLVersion.major >= 4 && GLVersion.minor >= 0)) {
01211         max_loaded_major = 4;
01212         max_loaded_minor = 0;
01213     }
01214 }
01215 
01216 int gladLoadGLLoader(GLADloadproc load) {
01217     GLVersion.major = 0; GLVersion.minor = 0;
01218     glGetString = (PFNGLGETSTRINGPROC)load("glGetString");
01219     if(glGetString == NULL) return 0;
01220     if(glGetString(GL_VERSION) == NULL) return 0;
01221     find_coreGL();
01222     load_GL_VERSION_1_0(load);
01223     load_GL_VERSION_1_1(load);
01224     load_GL_VERSION_1_2(load);
01225     load_GL_VERSION_1_3(load);
01226     load_GL_VERSION_1_4(load);
01227     load_GL_VERSION_1_5(load);
01228     load_GL_VERSION_2_0(load);
01229     load_GL_VERSION_2_1(load);
01230     load_GL_VERSION_3_0(load);
01231     load_GL_VERSION_3_1(load);
01232     load_GL_VERSION_3_2(load);
01233     load_GL_VERSION_3_3(load);
01234     load_GL_VERSION_4_0(load);
01235 
01236     if (!find_extensionsGL()) return 0;
01237     return GLVersion.major != 0 || GLVersion.minor != 0;
01238 }
